/**
 * Category identity ab SIRF yahan inject hoti hai:
 *
 *   categorySlug / categoryTitle / categoryIcon  <- folder name + services.ts
 *   item                                          <- page ka apna `title`
 *   image                                         <- services[cat].image
 *
 * Pehle ye paanch value har page file me apni copy thi (126 files x 5 = 630
 * duplicate values). Ab page file mein se hata diya gaya hai, to yahan ek hi
 * jagah se sabhi pages ko milti hain.
 */
function withCategory(
  categorySlug: string,
  page: Omit<
    GeneratedChildService,
    "categorySlug" | "categoryTitle" | "categoryIcon" | "item" | "image"
  > & { image?: string },
): GeneratedChildService {
  const meta = services.find((s) => s.slug === categorySlug);
  return {
    ...page,
    categorySlug,
    categoryTitle: meta?.title ?? categorySlug,
    categoryIcon: meta?.icon ?? "",
    item: page.title,
    image: page.image ?? meta?.image ?? "",
  };
}


